class DomainError(Exception):
    """Base of every business-rule failure, with a code and details."""

    def __init__(
        self,
        message: str,
        code: str = "DOMAIN_ERROR",
        details: dict[str, Any] | None = None,
    ) -> None:
        super().__init__(message)
        self.message = message
        self.code = code
        self.details = details if details is not None else {}

class InsufficientFundsError(DomainError):
    """The sender's balance is below the requested amount."""

    def __init__(
        self,
        message: str = "Insufficient funds for transfer",
        details: dict[str, Any] | None = None,
    ) -> None:
        super().__init__(message=message, code="INSUFFICIENT_FUNDS", details=details)

class AccountNotFoundError(DomainError):
    """A referenced account does not exist."""

    def __init__(
        self, message: str = "Account not found", details: dict[str, Any] | None = None
    ) -> None:
        super().__init__(message=message, code="ACCOUNT_NOT_FOUND", details=details)

@app.exception_handler(InsufficientFundsError)
async def insufficient_funds_handler(
    request: Request, exc: InsufficientFundsError
) -> JSONResponse:
    """Answer 402 with the error envelope."""
    req_id = request.headers.get("X-Request-ID") or str(uuid.uuid4())
    return JSONResponse(
        status_code=status.HTTP_402_PAYMENT_REQUIRED,
        content={
            "error": {
                "code": exc.code,
                "message": exc.message,
                "details": exc.details,
                "request_id": req_id,
            }
        },
        headers={"X-Request-ID": req_id},
    )

@app.exception_handler(AccountNotFoundError)
async def account_not_found_handler(
    request: Request, exc: AccountNotFoundError
) -> JSONResponse:
    """Answer 404 with the error envelope."""
    req_id = request.headers.get("X-Request-ID") or str(uuid.uuid4())
    return JSONResponse(
        status_code=status.HTTP_404_NOT_FOUND,
        content={
            "error": {
                "code": exc.code,
                "message": exc.message,
                "details": exc.details,
                "request_id": req_id,
            }
        },
        headers={"X-Request-ID": req_id},
    )

@app.post("/transfers", status_code=status.HTTP_200_OK)
async def create_transfer(payload: TransferRequest, request: Request) -> dict[str, Any]:
    """Move money between two accounts, or raise a domain error."""
    if payload.from_account not in ACCOUNTS_DB:
        raise AccountNotFoundError(
            message=f"Account '{payload.from_account}' not found",
            details={"account_id": payload.from_account},
        )
    if payload.to_account not in ACCOUNTS_DB:
        raise AccountNotFoundError(
            message=f"Account '{payload.to_account}' not found",
            details={"account_id": payload.to_account},
        )

    current_balance = ACCOUNTS_DB[payload.from_account]
    if current_balance < payload.amount:
        raise InsufficientFundsError(
            message=f"Account '{payload.from_account}' has insufficient balance",
            details={
                "available": current_balance,
                "requested": payload.amount,
                "shortfall": payload.amount - current_balance,
            },
        )

    ACCOUNTS_DB[payload.from_account] -= payload.amount
    ACCOUNTS_DB[payload.to_account] += payload.amount

    req_id = request.headers.get("X-Request-ID") or str(uuid.uuid4())
    return {
        "status": "completed",
        "from_account": payload.from_account,
        "to_account": payload.to_account,
        "amount": payload.amount,
        "remaining_balance": ACCOUNTS_DB[payload.from_account],
        "request_id": req_id,
    }

@app.get("/accounts/{account_id}")
async def get_account(account_id: str) -> dict[str, str | float]:
    """Return one account's balance."""
    if account_id not in ACCOUNTS_DB:
        raise AccountNotFoundError(
            message=f"Account '{account_id}' not found",
            details={"account_id": account_id},
        )
    return {"account_id": account_id, "balance": ACCOUNTS_DB[account_id]}
